<script>(function(){const rows=[...document.querySelectorAll('[data-result-correct]')],pager=document.querySelector('.oak-result-pager');if(!pager)return;let filter='all',page=1;function render(){const visible=rows.filter(x=>filter==='all'||x.dataset.resultCorrect==='no'),pages=Math.max(1,Math.ceil(visible.length/10));page=Math.min(page,pages);rows.forEach(x=>x.hidden=!visible.includes(x)||visible.indexOf(x)<(page-1)*10||visible.indexOf(x)>=page*10);pager.hidden=pages<=1;pager.querySelector('[data-result-page]').textContent='Page '+page+' of '+pages;pager.querySelector('[data-result-prev]').disabled=page===1;pager.querySelector('[data-result-next]').disabled=page===pages}document.querySelectorAll('[data-result-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.resultFilter;page=1;document.querySelectorAll('[data-result-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render()}));pager.querySelector('[data-result-prev]').addEventListener('click',()=>{page--;render()});pager.querySelector('[data-result-next]').addEventListener('click',()=>{page++;render()});render()})()</script>
</body></html>
